import { displayEthCompact } from '../app/scaling.js';
import { decimatorEntryName, decimatorWhole, decimatorTableField, decimatorCurrentCutoff } from './decimator-table.js';
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const amount = value => decimatorWhole(value).toLocaleString('en-US');
const compact = value => {
  const n = BigInt(value ?? 0);
  for (const [unit, suffix] of [[10n**15n,'Q'],[10n**12n,'T'],[10n**9n,'B'],[10n**6n,'M'],[1000n,'K']]) {
    if (n >= unit) {
      const tenths = (n * 10n + unit / 2n) / unit;
      return `${tenths / 10n}${tenths % 10n ? `.${tenths % 10n}` : ''}${suffix}`;
    }
  }
  return n.toLocaleString('en-US');
};
const bind = (host, name) => host.querySelector(`[data-bind="${name}"]`);
const prize = row => [BigInt(row.ethWei ?? 0) > 0n ? `${displayEthCompact(BigInt(row.ethWei))} ETH` : '',
  BigInt(row.halfPasses ?? 0) > 0n ? `${row.halfPasses} half ${BigInt(row.halfPasses) === 1n ? 'pass' : 'passes'}` : ''].filter(Boolean).join(' + ');

export function paintDecimatorHeader(host, skin, round = 0) {
  const { snapshot } = skin;
  const complete = round >= skin.frameCount;
  const logo = host.querySelector('.craps-dialog__brand-logo');
  logo.src = '/app/assets/decimator-logo.svg?v=casino-v2'; logo.alt = 'Decimator Craps Battle';
  bind(host, 'craps-dialog').setAttribute('aria-label', `Level ${snapshot.level} Decimator craps battle`);
  const marquee = bind(host, 'craps-prize-marquee'); marquee.hidden = false;
  for (const name of ['craps-jackpot-marquee','craps-biggest-marquee','craps-bounty-added']) bind(host, name).hidden = true;
  const bounty = bind(host, 'craps-bounty-marquee'); bounty.hidden = false;
  bind(host, 'craps-bounty-label').textContent = `LEVEL ${snapshot.level} · PRIZE POOL`;
  bind(host, 'craps-bounty-amount').textContent = displayEthCompact(BigInt(snapshot.poolWei ?? 0));
  bounty.querySelector('em').textContent = 'ETH';
  bounty.setAttribute('aria-label', `${displayEthCompact(BigInt(snapshot.poolWei ?? 0))} ETH and half whale passes`);
  const goal = bind(host, 'craps-title-goal'); goal.hidden = false;
  goal.querySelector('small').textContent = `${complete ? 'FINAL' : 'CURRENT'} TOP ${snapshot.winnerCount}`;
  goal.querySelector('em').textContent = complete ? 'SCORE' : 'PROVISIONAL';
  const cutoff = decimatorCurrentCutoff(skin, round);
  bind(host, 'craps-title-goal-amount').textContent = cutoff == null ? '—' : compact(cutoff);
  goal.setAttribute('aria-label', `${complete ? 'Final' : 'Provisional'} paid cutoff ${cutoff?.toLocaleString('en-US') ?? 'unavailable'} score. ${complete ? 'Tied scores use draw order.' : 'This boundary can rise; the final cutoff is only known at the end.'}`);
}

export function paintDecimatorStatus(host, skin, round, standings, bankroll = 0n) {
  const local = standings.find(row => row.local);
  bind(host, 'craps-race-rank').textContent = local?.rank ? `#${local.rank}` : 'OUT';
  bind(host, 'craps-race-left').textContent = String(standings.filter(row => row.state === 'live').length);
  bind(host, 'craps-race-total').textContent = String(skin.snapshot.fieldEntries ?? skin.snapshot.entrants);
  bind(host, 'craps-race-stack').textContent = compact(local?.amount);
  bind(host, 'craps-race-stack').title = (local?.amount ?? 0n).toLocaleString('en-US');
  bind(host, 'craps-race-stack-target').querySelector('small').textContent = 'PEAK SCORE';
  const note = bind(host, 'craps-decimator-note');
  if (note) {
    const start = decimatorWhole(skin.selected.stack);
    const live = start * bankroll / 3000n;
    note.textContent = `#${skin.selected.entryId} ${skin.selected.generated ? 'JACKPOT' : 'BURN'} · START ${compact(start)} · ${skin.selected.eligible ? `STACK ${compact(live)} · Peak score stays after bust.` : 'Eliminated in the opening draw.'}`;
    note.title = `${amount(skin.selected.stack)} credited starting stack. Peak score = starting stack × best completed-shooter multiple. The final paid cutoff is only revealed at the end.`;
  }
  paintDecimatorHeader(host, skin, round);
}

export function wireDecimatorField(host, skin) {
  const toggle = bind(host, 'craps-decimator-field-toggle');
  const panel = bind(host, 'craps-decimator-field');
  let offset = 0;
  const draw = () => {
    const page = decimatorTableField(skin, offset);
    panel.innerHTML = `<header><strong>OPENING DRAW · ${skin.snapshot.survivorCount} SURVIVED / ${page.total} ENTRIES</strong><button type="button" data-field-close>CLOSE FIELD</button></header>
      <p>Every burn and jackpot slot is included. Eliminated jackpot slots have no assigned wallet.</p>
      <ol>${page.rows.map(row => `<li data-entry-id="${esc(row.entryId)}" data-eligible="${row.eligible}"><span>#${esc(row.entryId)} · ${esc(decimatorEntryName(row, skin.names))}</span><span>${row.generated ? 'JACKPOT' : 'BURN'} · ${amount(row.stack)}</span><strong>${row.eligible ? 'SURVIVED' : 'ELIMINATED'}</strong></li>`).join('')}</ol>
      <footer><button type="button" data-field-prev ${offset === 0 ? 'disabled' : ''}>PREV</button><span>${offset + 1}–${offset + page.rows.length} / ${page.total}</span><button type="button" data-field-next ${offset + page.rows.length >= page.total ? 'disabled' : ''}>NEXT</button></footer>`;
    panel.querySelector('[data-field-close]').onclick = () => { panel.hidden = true; toggle.setAttribute('aria-expanded', 'false'); toggle.focus(); };
    panel.querySelector('[data-field-prev]').onclick = () => { offset = Math.max(0,offset - 25); draw(); };
    panel.querySelector('[data-field-next]').onclick = () => { offset += 25; draw(); };
  };
  toggle.textContent = `FULL FIELD · ${skin.snapshot.fieldEntries ?? skin.snapshot.entrants}`;
  toggle.onclick = () => { panel.hidden = !panel.hidden; toggle.setAttribute('aria-expanded', String(!panel.hidden)); if (!panel.hidden) { draw(); panel.querySelector('button').focus(); } };
  panel.hidden = true;
}

export function paintDecimatorResult(host, skin, standings) {
  const { snapshot } = skin;
  const local = standings.find(row => row.local);
  const ownedWins = snapshot.winners.filter(row => row.address?.toLowerCase() === snapshot.you?.address?.toLowerCase());
  const splash = bind(host, 'craps-race-result');
  const card = bind(host, 'craps-race-result-card');
  card.innerHTML = `<img class="craps-decimator-result-logo" src="/app/assets/decimator-logo.svg?v=casino-v2" alt="Decimator">
    <h2>${ownedWins.length ? 'IN THE MONEY' : skin.selected.eligible ? 'BATTLE COMPLETE' : 'DRAW ELIMINATED'}</h2>
    <p>${amount(skin.selected.stack)} starting stack · ${local?.amount.toLocaleString('en-US') ?? '0'} peak score${local?.rank ? ` · #${local.rank}` : ''}</p>
    <p>${ownedWins.length ? esc(ownedWins.map(row => prize(row)).join(' + ')) : 'No prize for this wallet.'}</p>
    <p>Final paid cutoff: <b>${amount(snapshot.winners.at(-1)?.score)}</b> · ties use draw order</p>
    <ol class="craps-decimator-winners">${snapshot.winners.map(row => `<li><b>#${row.rank} ${esc(decimatorEntryName(row, skin.names))}</b><span>${amount(row.score)} SCORE</span><strong>${esc(prize(row))}</strong></li>`).join('')}</ol>
    <button type="button" class="craps-race-result__exit" data-bind="craps-race-exit">DONE</button>`;
  splash.hidden = false; splash.removeAttribute('hidden'); splash.classList.add('is-visible');
  bind(host, 'craps-dice-bay').setAttribute('aria-label', 'Decimator battle complete. Prizes are shown in ETH and half whale passes.');
  card.querySelector('button').focus();
}
